def transform(grid):
    h, w = len(grid), len(grid[0])
    row_bars = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    def intervals(n, bars):
        out, start = [], 0
        for b in bars:
            if start < b:
                out.append((start, b))
            start = b + 1
        if start < n:
            out.append((start, n))
        return out
    rs, cs = intervals(h, row_bars), intervals(w, col_bars)
    def block(pos, spans):
        for i, (a, b) in enumerate(spans):
            if a <= pos < b:
                return i
        return None
    marks = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 8):
                marks.setdefault(v, set()).add((block(r, rs), block(c, cs)))
    painted = {}
    for color, points in marks.items():
        pts = sorted(points)
        for i, p in enumerate(pts):
            for q in pts[i+1:]:
                if p[0] == q[0] or p[1] == q[1]:
                    dr = (q[0] > p[0]) - (q[0] < p[0])
                    dc = (q[1] > p[1]) - (q[1] < p[1])
                    x, y = p
                    while True:
                        if x is not None and y is not None:
                            old = painted.get((x, y))
                            painted[(x, y)] = color if old is None or old == color else 6
                        if (x, y) == q:
                            break
                        x, y = x + dr, y + dc
    out = [row[:] for row in grid]
    for (bi, bj), color in painted.items():
        r0, r1 = rs[bi]
        c0, c1 = cs[bj]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
